-- Синтетические штрихи для rose.detect (срез 1 карты): формат штриха виджета — { p = { x1, y1, x2, y2, … } },
-- экранные пиксели PW2 (758 × 1024). Дрожание пальца — детерминированное (своё ЛКГ), без math.random.
-- Розы: круг (обход ≥ 300°) и две почти прямые черты накрест внутри. Не-розы — то, что пишут на странице.
local F = {}

local seed = 20261106
local function jitter(a)
  seed = (seed * 1103515245 + 12345) % 2147483648
  return (seed % 1000) / 1000 * 2 * a - a
end

-- дуга: центр, радиусы по осям, от a0 до a1 градусов, шаг ~5°, дрожание j px; tilt — поворот эллипса
local function arc(cx, cy, rx, ry, a0, a1, j, tilt)
  local p = {}
  local n = math.max(2, math.floor(math.abs(a1 - a0) / 5))
  local tr = math.rad(tilt or 0)
  for i = 0, n do
    local a = math.rad(a0 + (a1 - a0) * i / n)
    local x, y = rx * math.cos(a), ry * math.sin(a)
    p[#p + 1] = math.floor(cx + x * math.cos(tr) - y * math.sin(tr) + jitter(j) + 0.5)
    p[#p + 1] = math.floor(cy + x * math.sin(tr) + y * math.cos(tr) + jitter(j) + 0.5)
  end
  return { p = p }
end

-- черта от (x0, y0) к (x1, y1), точки через ~6 px, дрожание j px
local function bar(x0, y0, x1, y1, j)
  local p = {}
  local n = math.max(2, math.floor(math.max(math.abs(x1 - x0), math.abs(y1 - y0)) / 6))
  for i = 0, n do
    p[#p + 1] = math.floor(x0 + (x1 - x0) * i / n + jitter(j) + 0.5)
    p[#p + 1] = math.floor(y0 + (y1 - y0) * i / n + jitter(j) + 0.5)
  end
  return { p = p }
end

-- ломаная по вершинам (буквы, квадрат), точки через ~6 px между вершинами
local function poly(pts, j)
  local p = {}
  for k = 1, #pts - 2, 2 do
    local s = bar(pts[k], pts[k + 1], pts[k + 2], pts[k + 3], j).p
    for i = (k == 1) and 1 or 3, #s do p[#p + 1] = s[i] end
  end
  return { p = p }
end

