-- розы рукой, как их рисуют люди (владелец 2026-11-16: «концы линий могут сильно разлетаться друг за друга»):
-- круг не замкнут точно, неровный, черты с росчерком на концах

-- радиус по ходу круга: r(a) = r0 + сумма гармоник, a в градусах; конец штриха может уходить внутрь (drift)
local function loop(cx, cy, r0, a0, a1, j, opts)
  opts = opts or {}
  local p = {}
  local n = math.max(2, math.floor(math.abs(a1 - a0) / 5))
  for i = 0, n do
    local f = i / n
    local a = a0 + (a1 - a0) * f
    local r = r0 + (opts.wave or 0) * math.sin(math.rad(a * (opts.lobes or 3) + (opts.phase or 0)))
    if opts.drift and f > opts.drift_from then r = r + opts.drift * (f - opts.drift_from) / (1 - opts.drift_from) end
    local rx, ry = r * (opts.sx or 1), r * (opts.sy or 1)
    p[#p + 1] = math.floor(cx + rx * math.cos(math.rad(a)) + jitter(j) + 0.5)
    p[#p + 1] = math.floor(cy + ry * math.sin(math.rad(a)) + jitter(j) + 0.5)
  end
  return { p = p }
end

-- черта с росчерком: последние hook px уходят вбок под углом deg
local function flick(x0, y0, x1, y1, j, hook, deg)
  local s = bar(x0, y0, x1, y1, j).p
  local len = math.sqrt((x1 - x0) ^ 2 + (y1 - y0) ^ 2)
  local ux, uy = (x1 - x0) / len, (y1 - y0) / len
  local c, sn = math.cos(math.rad(deg)), math.sin(math.rad(deg))
  local hx, hy = ux * c - uy * sn, ux * sn + uy * c
  for k = 1, 4 do
    s[#s + 1] = math.floor(x1 + hx * hook * k / 4 + 0.5)
    s[#s + 1] = math.floor(y1 + hy * hook * k / 4 + 0.5)
  end
  return { p = s }
end

