-- круг и две дуги накрест: прогиб ~0.3 хорды — черты не прямые
F.arcs_cross = (function()
  local function sag(x0, y0, x1, y1, k)
    local p, n = {}, 40
    local nx, ny = -(y1 - y0), x1 - x0
    for i = 0, n do
      local f = i / n
      local h = 4 * k * f * (1 - f)
      p[#p + 1] = math.floor(x0 + (x1 - x0) * f + nx * h + jitter(2) + 0.5)
      p[#p + 1] = math.floor(y0 + (y1 - y0) * f + ny * h + jitter(2) + 0.5)
    end
    return { p = p }
  end
  return { loop(380, 500, 150, 0, -365, 4), sag(380, 340, 380, 660, 0.3), sag(220, 500, 540, 500, 0.3) }
end)()

